    for dx, dy in moves:
        x1, y1 = sx + dx, sy + dy
        if not inb(x1, y1):
            continue
        # 1-ply lookahead for better frontier capture.
        best2 = float("-inf")
        for ddx, ddy in moves:
            x2, y2 = x1 + ddx, y1 + ddy
            if not inb(x2, y2):
