                obs_adj += 1
        v -= obs_adj

        # Early/mid game: expand; late game: stabilize control
        tr = int(observation["turn_index"])
        if tr < 0.6 * int(observation["turns_remaining"]) + tr:
            v += 0.3 * count_adj(unclaimed, x, y)
        else:
            v += 0.5 * (1 if (x, y) in self_terr else 0)

        # Tiny tie-break: prefer moves increasing manhattan distance from our exact corner (anti-stall)
        corner = (0, 0) if (sx + sy) <= (w - 1 - sx + h - 1 - sy) else (w - 1, h - 1)
        v += 0.01 * (abs(x - corner[0]) + abs(y - corner[1]))
        return v

    best = None
    bestv = -10**18
    for dx, dy in moves:
        nx, ny = sx + dx, sy + dy
        v = heuristic(nx, ny) if inb(nx, ny) else -10**9
        if v > bestv:
            bestv = v
            best = (dx, dy)
        elif v == bestv and best is not None:
            if (dx, dy) < best:
                best = (dx, dy)

    return [int(best[0]), int(best[1])]

